/**
 * Umfaris WhatsApp Agent — n8n "Code" node (Run Once for All Items).
 *
 * Pipeline: WhatsApp webhook -> THIS node -> replies on WhatsApp.
 * - Whitelist gate (only ALLOWED_NUMBERS get a reply).
 * - Gemini (free tier) function-calling loop over a fixed set of booking actions.
 * - Firestore via the Firebase Auth REST "bot" user (no service account).
 * - Per-sender conversation memory in n8n workflow static data (enables
 *   confirm-before-write across messages).
 *
 * Fill the CONFIG block, then this node needs no other nodes except a Webhook
 * (POST) trigger feeding it `items[0].json.body`.
 *
 * Uses n8n's built-in `this.helpers.httpRequest` — no npm modules required.
 */

// ============================ CONFIG ============================
const CONFIG = {
  // WhatsApp Cloud API
  WA_PHONE_NUMBER_ID: '1216368424887112',
  WA_TOKEN: 'PASTE_WHATSAPP_TOKEN', // temp 24h token now; swap for System User token later
  WA_API_VERSION: 'v21.0',

  // Whitelist = active users in إدارة المستخدمين (the `users` collection). The bot only
  // replies to a sender whose phone is registered there. EXTRA_ALLOWED is an optional
  // always-allow list (digits only) on top of that; leave empty to allow ONLY registered users.
  EXTRA_ALLOWED: [],
  WHITELIST_TTL_MS: 60000, // cache the users whitelist this long to avoid re-reading every message

  // Google Gemini (free tier — key from https://aistudio.google.com/app/apikey)
  GEMINI_API_KEY: 'PASTE_GEMINI_KEY',
  GEMINI_MODEL: 'gemini-2.5-flash', // free tier in this account/region (2.0-flash was limit:0 here)

  // Firebase (public web config — safe to embed) + bot app-user credentials
  FB_API_KEY: 'AIzaSyAU6H9FZY0PR6-3JE3KGuwskKPbWbjwTew',
  FB_PROJECT_ID: 'umfaris-1efca',
  BOT_EMAIL: 'bot@umfaris.com',
  BOT_PASSWORD: 'PASTE_BOT_PASSWORD',

  MAX_TOOL_ROUNDS: 6,        // safety cap on the agent loop
  HISTORY_TURNS: 20,         // how many past messages to keep per sender
};
// ================================================================

const http = (opts) => this.helpers.httpRequest(opts);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const FS_BASE = `https://firestore.googleapis.com/v1/projects/${CONFIG.FB_PROJECT_ID}/databases/(default)/documents`;
const staticData = $getWorkflowStaticData('global');

// ---------- Firestore value (de)serialization ----------
function toFsValue(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === 'boolean') return { booleanValue: v };
  if (typeof v === 'number') return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (typeof v === 'string') return { stringValue: v };
  if (Array.isArray(v)) return { arrayValue: { values: v.map(toFsValue) } };
  if (typeof v === 'object') return { mapValue: { fields: toFsFields(v) } };
  return { stringValue: String(v) };
}
function toFsFields(obj) {
  const f = {};
  for (const k of Object.keys(obj)) f[k] = toFsValue(obj[k]);
  return f;
}
function fromFsValue(val) {
  if (!val) return null;
  if ('nullValue' in val) return null;
  if ('booleanValue' in val) return val.booleanValue;
  if ('integerValue' in val) return parseInt(val.integerValue, 10);
  if ('doubleValue' in val) return val.doubleValue;
  if ('stringValue' in val) return val.stringValue;
  if ('arrayValue' in val) return (val.arrayValue.values || []).map(fromFsValue);
  if ('mapValue' in val) return fromFsFields(val.mapValue.fields || {});
  if ('timestampValue' in val) return val.timestampValue;
  return null;
}
function fromFsFields(fields) {
  const o = {};
  for (const k of Object.keys(fields || {})) o[k] = fromFsValue(fields[k]);
  return o;
}
function docId(name) { return name.split('/').pop(); }

// ---------- Firebase auth (bot user) ----------
async function getIdToken() {
  const now = Date.now();
  if (staticData.fbToken && staticData.fbTokenExp && now < staticData.fbTokenExp - 60000) {
    return staticData.fbToken;
  }
  const res = await http({
    method: 'POST',
    url: `https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${CONFIG.FB_API_KEY}`,
    body: { email: CONFIG.BOT_EMAIL, password: CONFIG.BOT_PASSWORD, returnSecureToken: true },
    json: true,
  });
  staticData.fbToken = res.idToken;
  staticData.fbTokenExp = now + parseInt(res.expiresIn || '3600', 10) * 1000;
  return res.idToken;
}
async function fsRequest(method, path, body) {
  const token = await getIdToken();
  return http({
    method,
    url: `${FS_BASE}${path}`,
    headers: { Authorization: `Bearer ${token}` },
    body: body || undefined,
    json: true,
  });
}

// ---------- Firestore helpers tied to the umfaris schema ----------
async function bookingsOnDate(date) {
  const res = await fsRequest('POST', ':runQuery', {
    structuredQuery: {
      from: [{ collectionId: 'bookings' }],
      where: { fieldFilter: { field: { fieldPath: 'date' }, op: 'EQUAL', value: { stringValue: date } } },
    },
  });
  return (res || []).filter(r => r.document).map(r => ({ id: docId(r.document.name), ...fromFsFields(r.document.fields) }));
}
async function bookingsInRange(from, to) {
  const res = await fsRequest('POST', ':runQuery', {
    structuredQuery: {
      from: [{ collectionId: 'bookings' }],
      where: { compositeFilter: { op: 'AND', filters: [
        { fieldFilter: { field: { fieldPath: 'date' }, op: 'GREATER_THAN_OR_EQUAL', value: { stringValue: from } } },
        { fieldFilter: { field: { fieldPath: 'date' }, op: 'LESS_THAN_OR_EQUAL', value: { stringValue: to } } },
      ] } },
      orderBy: [{ field: { fieldPath: 'date' } }],
    },
  });
  return (res || []).filter(r => r.document).map(r => ({ id: docId(r.document.name), ...fromFsFields(r.document.fields) }));
}
async function getSettings() {
  try {
    const d = await fsRequest('GET', '/settings/config');
    return fromFsFields(d.fields || {});
  } catch (e) { return { maxPerDay: -1, dayOverrides: {} }; }
}
function capForDate(settings, date) {
  const ov = settings.dayOverrides || {};
  return (date in ov) ? ov[date] : (typeof settings.maxPerDay === 'number' ? settings.maxPerDay : -1);
}

// ---------- Whitelist: only active users from إدارة المستخدمين may talk to the bot ----------
function normPhone(s) { return String(s || '').replace(/\D/g, ''); }
function phoneMatches(a, b) { // both normalized to digits
  if (!a || !b) return false;
  if (a === b) return true;
  const [lo, hi] = a.length <= b.length ? [a, b] : [b, a];
  return lo.length >= 8 && hi.endsWith(lo); // tolerate missing country code / leading zeros
}
async function activeUserPhones() {
  const now = Date.now();
  if (staticData.wl && staticData.wlExp && now < staticData.wlExp) return staticData.wl;
  const res = await fsRequest('GET', '/users');
  const phones = (res.documents || [])
    .map(d => fromFsFields(d.fields || {}))
    .filter(u => (u.status || 'active') === 'active')
    .map(u => normPhone(u.phone))
    .filter(p => p.length >= 8);
  staticData.wl = phones;
  staticData.wlExp = now + CONFIG.WHITELIST_TTL_MS;
  return phones;
}
async function isAllowed(from) {
  const f = normPhone(from);
  if (CONFIG.EXTRA_ALLOWED.map(normPhone).some(p => phoneMatches(f, p))) return true;
  return (await activeUserPhones()).some(p => phoneMatches(f, p));
}

// New-booking document with all BookingModel defaults filled in.
function newBookingDoc(p, status) {
  return {
    clientId: '', clientName: p.clientName || '', clientPhone: p.clientPhone || '',
    date: p.date, eventTime: p.eventTime || '', eventType: p.eventType || '', city: p.city || '',
    locationType: '', guests: p.guests || 0, materialType: '', materialColor: '',
    sabbabatCount: 0, workersCount: 0, clothesType: '', clothesColor: '',
    amount: p.amount || 0, discount: 0, paidAmount: 0, paymentStatus: 'unpaid',
    status, tipsAmount: 0, tipsDistributed: false, paymentCompleted: false,
    closed: false, notes: p.notes || '', staff: [], customFields: {},
  };
}

// ---------- The tools the model may call ----------
async function runTool(name, input) {
  if (name === 'check_availability') {
    const settings = await getSettings();
    const cap = capForDate(settings, input.date);
    const active = (await bookingsOnDate(input.date)).filter(b => b.status === 'active').length;
    const remaining = cap === -1 ? -1 : Math.max(cap - active, 0);
    return { date: input.date, active_count: active, cap, remaining, is_full: cap !== -1 && active >= cap };
  }
  if (name === 'list_bookings') {
    const list = await bookingsInRange(input.date, input.to_date || input.date);
    return { bookings: list.map(b => ({ id: b.id, clientName: b.clientName, clientPhone: b.clientPhone, date: b.date, eventTime: b.eventTime, guests: b.guests, status: b.status })) };
  }
  if (name === 'create_booking') {
    const settings = await getSettings();
    const cap = capForDate(settings, input.date);
    const active = (await bookingsOnDate(input.date)).filter(b => b.status === 'active').length;
    const status = (cap !== -1 && active >= cap) ? 'pending' : 'active';
    const res = await fsRequest('POST', '/bookings', { fields: toFsFields(newBookingDoc(input, status)) });
    return { id: docId(res.name), status, waitlisted: status === 'pending' };
  }
  if (name === 'edit_booking') {
    const changes = input.changes || {};
    const keys = Object.keys(changes);
    if (!keys.length) return { error: 'no changes provided' };
    const mask = keys.map(k => `updateMask.fieldPaths=${encodeURIComponent(k)}`).join('&');
    const res = await fsRequest('PATCH', `/bookings/${input.id}?${mask}`, { fields: toFsFields(changes) });
    return { id: docId(res.name), updated: keys };
  }
  if (name === 'cancel_booking') {
    const res = await fsRequest('PATCH', `/bookings/${input.id}?updateMask.fieldPaths=status`, { fields: { status: { stringValue: 'cancelled' } } });
    return { id: docId(res.name), status: 'cancelled' };
  }
  if (name === 'set_waiting_status') {
    const status = input.action === 'confirm' ? 'active' : 'rejected';
    const res = await fsRequest('PATCH', `/bookings/${input.id}?updateMask.fieldPaths=status`, { fields: { status: { stringValue: status } } });
    return { id: docId(res.name), status };
  }
  return { error: `unknown tool ${name}` };
}

// Tools in Gemini "function_declarations" format (types are the OpenAPI enum, uppercase).
const FUNCTION_DECLARATIONS = [
  { name: 'check_availability', description: 'تتحقق من توفّر يوم: كم حجز نشط وكم يتبقّى حسب الحد الأقصى.',
    parameters: { type: 'OBJECT', properties: { date: { type: 'STRING', description: 'YYYY-MM-DD' } }, required: ['date'] } },
  { name: 'list_bookings', description: 'تعرض حجوزات يوم (أو مدى من تاريخ إلى تاريخ).',
    parameters: { type: 'OBJECT', properties: { date: { type: 'STRING', description: 'YYYY-MM-DD' }, to_date: { type: 'STRING', description: 'اختياري: نهاية المدى YYYY-MM-DD' } }, required: ['date'] } },
  { name: 'create_booking', description: 'تنشئ حجزاً. إن كان اليوم ممتلئاً يُحفظ كقائمة انتظار (pending).',
    parameters: { type: 'OBJECT', properties: {
      clientName: { type: 'STRING' }, clientPhone: { type: 'STRING' }, date: { type: 'STRING', description: 'YYYY-MM-DD' },
      eventTime: { type: 'STRING' }, eventType: { type: 'STRING' }, city: { type: 'STRING' },
      guests: { type: 'INTEGER' }, amount: { type: 'NUMBER' }, notes: { type: 'STRING' },
    }, required: ['clientName', 'date'] } },
  { name: 'edit_booking', description: 'تعدّل حقول حجز قائم. مرّري فقط الحقول المراد تغييرها داخل changes.',
    parameters: { type: 'OBJECT', properties: {
      id: { type: 'STRING', description: 'معرّف الحجز' },
      changes: { type: 'OBJECT', properties: {
        date: { type: 'STRING' }, eventTime: { type: 'STRING' }, guests: { type: 'INTEGER' },
        city: { type: 'STRING' }, amount: { type: 'NUMBER' }, notes: { type: 'STRING' }, eventType: { type: 'STRING' },
      } },
    }, required: ['id', 'changes'] } },
  { name: 'cancel_booking', description: 'تلغي حجزاً (status=cancelled).',
    parameters: { type: 'OBJECT', properties: { id: { type: 'STRING' } }, required: ['id'] } },
  { name: 'set_waiting_status', description: 'تؤكّد/ترفض حجز انتظار. confirm→active, reject→rejected.',
    parameters: { type: 'OBJECT', properties: { id: { type: 'STRING' }, action: { type: 'STRING', enum: ['confirm', 'reject'] } }, required: ['id', 'action'] } },
];

function systemPrompt() {
  const today = new Date().toISOString().slice(0, 10);
  return `اسمك "حمودي ودي"، مساعد ودود لإدارة حجوزات شركة "أم فارس" للضيافة. تستقبل الطلبات عبر واتساب وتنفّذها على نظام الحجوزات.
- افهم الطلب بالعربية واختر الأداة المناسبة من المتاحة فقط.
- اليوم هو ${today}. حوّل أي تاريخ إلى صيغة YYYY-MM-DD الميلادية. لو كان غامضاً اسأل سؤالاً قصيراً واحداً.
- قبل أي إنشاء/تعديل/إلغاء: اعرض ملخصاً واطلب تأكيداً، ولا تنفّذ إلا بعد أن يؤكّد المستخدم (نعم/تأكيد/✅). أما القراءة (التوفّر/عرض الحجوزات) فنفّذها فوراً.
- لو امتلأ اليوم سيوضع الحجز في قائمة الانتظار — أخبر المستخدم بذلك بوضوح.
- ردودك قصيرة وودّية وعملية بالعربية. عرّف عن نفسك باسم "حمودي" في أول رسالة، وأكّد النتيجة بعد كل تنفيذ.
- ما هو خارج صلاحياتك (المستخدمون، الإعدادات، الإغلاق المالي/الإكراميات، الحذف النهائي) اعتذر عنه بلطف.`;
}

// ---------- WhatsApp ----------
async function sendWhatsApp(to, text) {
  await http({
    method: 'POST',
    url: `https://graph.facebook.com/${CONFIG.WA_API_VERSION}/${CONFIG.WA_PHONE_NUMBER_ID}/messages`,
    headers: { Authorization: `Bearer ${CONFIG.WA_TOKEN}` },
    body: { messaging_product: 'whatsapp', to, type: 'text', text: { body: text } },
    json: true,
  });
}

// ---------- Gemini agent loop ----------
// history entries are Gemini "contents": { role: 'user'|'model', parts: [...] }
async function runAgent(from, userText) {
  staticData.sessions = staticData.sessions || {};
  const history = staticData.sessions[from] || [];
  history.push({ role: 'user', parts: [{ text: userText }] });

  let reply = 'تم.';
  for (let round = 0; round < CONFIG.MAX_TOOL_ROUNDS; round++) {
    // Call Gemini, retrying transient overload/rate-limit (503 / 429).
    let res;
    for (let attempt = 0; attempt < 4; attempt++) {
      res = await http({
        method: 'POST',
        url: `https://generativelanguage.googleapis.com/v1beta/models/${CONFIG.GEMINI_MODEL}:generateContent?key=${CONFIG.GEMINI_API_KEY}`,
        headers: { 'content-type': 'application/json' },
        body: {
          system_instruction: { parts: [{ text: systemPrompt() }] },
          contents: history,
          tools: [{ function_declarations: FUNCTION_DECLARATIONS }],
        },
        json: true,
      });
      const code = res && res.error && res.error.code;
      if (code === 503 || code === 429) { await sleep(1500 * (attempt + 1)); continue; }
      break;
    }
    if (res && res.error) throw new Error(`Gemini ${res.error.code}: ${res.error.message}`);

    const cand = res.candidates && res.candidates[0];
    const parts = (cand && cand.content && cand.content.parts) || [];
    history.push({ role: 'model', parts });

    const calls = parts.filter(p => p.functionCall);
    if (calls.length) {
      const responseParts = [];
      for (const p of calls) {
        let out;
        try { out = await runTool(p.functionCall.name, p.functionCall.args || {}); }
        catch (e) { out = { error: String(e.message || e) }; }
        responseParts.push({ functionResponse: { name: p.functionCall.name, response: out } });
      }
      history.push({ role: 'user', parts: responseParts });
      continue; // let the model see results and respond / call more tools
    }

    // final text answer
    reply = parts.filter(p => p.text).map(p => p.text).join('\n').trim() || reply;
    break;
  }

  // trim + persist history
  staticData.sessions[from] = history.slice(-CONFIG.HISTORY_TURNS);
  return reply;
}

// ============================ MAIN ============================
const body = items[0].json.body || items[0].json;
let value, msg;
try {
  value = body.entry[0].changes[0].value;
  msg = value.messages && value.messages[0];
} catch (e) { return [{ json: { ignored: 'no-entry' } }]; }

// Ignore delivery/read status callbacks and non-text messages.
if (!msg || msg.type !== 'text') return [{ json: { ignored: 'no-text-message' } }];

const from = msg.from; // digits, no +
const text = msg.text.body;

// Whitelist gate — only active users registered in إدارة المستخدمين get a reply.
if (!(await isAllowed(from))) {
  return [{ json: { ignored: 'not-registered', from } }];
}

let replyText;
try {
  replyText = await runAgent(from, text);
} catch (e) {
  replyText = 'صار خطأ تقني، حاولي مرة ثانية بعد قليل.';
  await sendWhatsApp(from, replyText);
  return [{ json: { error: String(e.message || e), from } }];
}

await sendWhatsApp(from, replyText);
return [{ json: { from, in: text, out: replyText } }];
